def longestXorSubarray(nums, target):
    first = {0: 0}
    px = 0
    best = 0
    for j, x in enumerate(nums, 1):
        px ^= x
        i = first.get(px ^ target)
        if i is not None and j - i > best:
            best = j - i
        if px not in first:
            first[px] = j
    return best
